trigger.script:
local posr1 = random(10) local posrr1={ CVector(7096.887, 251.511, 524.762), CVector(6494.388, 256.065, 791.483), CVector(5533.235, 247.101, 646.046), CVector(6999.741, 246.419, 859.777), CVector(7135.897, 270.999, 1594.224), CVector(6546.896, 256.152, 2260.690), CVector(6117.170, 270.138, 2561.633), CVector(7371.443, 223.531, 1960.418), CVector(7999.273, 226.466, 2746.604), CVector(6879.807, 226.949, 3461.883)}
local posr2 = random(10) local posrr2={ CVector(5770.631, 208.864, 4243.322), CVector(5666.647, 212.885, 4777.477), CVector(4900.090, 233.795, 4973.739), CVector(4514.838, 242.744, 4715.496), CVector(4201.402, 261.296, 3874.374), CVector(4605.746, 265.409, 3405.248), CVector(4304.126, 247.700, 2415.274), CVector(3975.037, 244.840, 769.116), CVector(4399.409, 214.824, 928.731), CVector(4479.127, 212.037, 1279.993)}
local posr_scav1={ CVector(5613.020, 216.573, 1084.168), CVector(5852.572, 238.424, 1135.578), CVector(5987.480, 245.991, 871.976), CVector(7355.271, 249.227, 2411.834), CVector(7345.678, 226.972, 2850.049), CVector(7237.014, 219.630, 3166.718), CVector(6792.051, 250.218, 3013.096), CVector(5412.767, 228.956, 2206.780)}
local posr_scav2={ CVector(5277.207, 237.487, 5201.297), CVector(5233.958, 263.437, 4815.378), CVector(5007.909, 234.721, 5327.070), CVector(4705.930, 280.920, 4204.618), CVector(4606.604, 280.868, 3953.746), CVector(3964.326, 251.492, 1790.708), CVector(4611.425, 247.476, 2544.672)}
local rotarr={ Quaternion(-0.029, 0.679, -0.021, 0.734), Quaternion(0.001, 0.626, 0.002, 0.780), Quaternion(-0.001, 0.558, -0.001, 0.830), Quaternion(-0.029, -0.025, 0.005, 0.999), Quaternion(-0.001, -0.346, 0.001, 0.938), Quaternion(-0.001, -0.724, -0.000, 0.690), Quaternion(-0.025, -0.992, -0.005, 0.125), Quaternion(0.002, -0.914, -0.001, 0.405), Quaternion(-0.003, -1.000, -0.006, -0.015)}
local spawns = random(2) if spawns == 1 then SetVar("SpawnPlayer", 1) if not(GetVar("PlayerBelong").AsString == "SCAV") then SetVar("PosPlayer1", posr1) --TActivate("Exits_RidzinBaseTroiskoe") else --TActivate("ExitsForScav_RidzinBaseScavTroiskoe") end else SetVar("SpawnPlayer", 2) if not(GetVar("PlayerBelong").AsString == "SCAV") then SetVar("PosPlayer2", posr2) --TActivate("Exits_FaterTownGloohoe") else --TActivate("ExitsForScav_FaterGloohoeTheTown") end end
local vehPlayer = GetPlayerVehicle() if vehPlayer then vehPlayer:SetRotation(rotarr[random(getn(rotarr))]) vehPlayer:setImmortalMode(1) if spawns == 1 then if not(GetVar("PlayerBelong").AsString == "SCAV") then vehPlayer:SetGamePositionOnGround(posrr1[posr1]) else vehPlayer:SetGamePositionOnGround(posr_scav1[random(getn(posr_scav1))]) end else if not(GetVar("PlayerBelong").AsString == "SCAV") then vehPlayer:SetGamePositionOnGround(posrr2[posr2]) else vehPlayer:SetGamePositionOnGround(posr_scav2[random(getn(posr_scav2))]) end end if GetVar("PlayerBelong").AsString == "SCAV" then vehPlayer:SetNameFromScript("ScavCarForPlayer") getObj("FakePlayerDead"):DelEvent("GE_VEHICLE_WITHOUT_HEALTH") getObj("FakePlayerDead"):AddEvent("GE_VEHICLE_WITHOUT_HEALTH", "ScavCarForPlayer") else vehPlayer:SetNameFromScript("PlayerCar") getObj("FakePlayerDead"):DelEvent("GE_VEHICLE_WITHOUT_HEALTH") getObj("FakePlayerDead"):AddEvent("GE_VEHICLE_WITHOUT_HEALTH", "PlayerCar") end vehPlayer:SetThrottle(0) vehPlayer:SetCustomLinearVelocity(0) end
TActivate("SpawnsScavs") TActivate("FakePlayerDead")
if GetVar("PlayerBelong").AsString ~= "SCAV" then if EVENT == "1_APRIL" or EVENT == "1_APRIL_MULTIPLAYER" then TActivate("TpFollowPlayerCarsToPlayer") end end
trigger:Deactivate()
